components.css:
.ds-rsvp-primary { display: inline-flex; width: 100%; min-height: 56px; align-items: center; justify-content: space-between; gap: 24px; border-radius: 12px; padding: 16px 24px; background: var(--wine); color: var(--paper); font-family: var(--font-manrope), Arial, sans-serif; font-size: 14px; font-weight: 600; line-height: 20px; text-align: left; text-decoration: none; transition: background-color 200ms; }
.ds-rsvp-primary:hover { background: var(--berry); }
.ds-rsvp-primary:focus-visible { outline: 2px solid var(--leaf); outline-offset: 4px; }
.ds-rsvp-primary svg { width: 20px; height: 20px; flex: none; fill: none; stroke: currentColor; stroke-width: 1.5; stroke-linecap: round; stroke-linejoin: round; transition: transform 200ms; }
.ds-rsvp-primary:hover svg { transform: translate(2px, -2px); }

.ds-rsvp-light { display: inline-flex; width: 100%; min-height: 56px; align-items: center; justify-content: space-between; gap: 24px; border-radius: 12px; padding: 16px 24px; background: var(--paper); color: var(--wine); font-family: var(--font-manrope), Arial, sans-serif; font-size: 14px; font-weight: 600; line-height: 20px; text-align: left; text-decoration: none; transition: background-color 200ms; }
.ds-rsvp-light:hover { background: var(--pinkwash); }
.ds-rsvp-light:focus-visible { outline: 2px solid var(--leaf); outline-offset: 4px; }
.ds-rsvp-light svg { width: 20px; height: 20px; flex: none; fill: none; stroke: currentColor; stroke-width: 1.5; stroke-linecap: round; stroke-linejoin: round; transition: transform 200ms; }
.ds-rsvp-light:hover svg { transform: translate(2px, -2px); }

.ds-map-link { display: inline-flex; min-height: 44px; align-items: center; gap: 8px; border: 1px solid var(--leaf); border-radius: 8px; padding: 8px 16px; background: var(--paper); color: var(--leaf); font-family: var(--font-manrope), Arial, sans-serif; font-size: 14px; font-weight: 600; line-height: 20px; text-decoration: none; transition: background-color 200ms, color 200ms; }
.ds-map-link:hover { background: var(--leaf); color: var(--paper); }
.ds-map-link:focus-visible { outline: 2px solid var(--leaf); outline-offset: 4px; }
.ds-map-link svg { width: 16px; height: 16px; flex: none; fill: none; stroke: currentColor; stroke-width: 1.5; stroke-linecap: round; stroke-linejoin: round; transition: transform 200ms; }
.ds-map-link:hover svg { transform: translate(2px, -2px); }

.ds-alias-copy { display: inline-flex; min-height: 48px; align-items: center; justify-content: center; border: 1px solid var(--berry); border-radius: 8px; padding: 12px 20px; background: var(--paper); color: var(--berry); font-family: var(--font-manrope), Arial, sans-serif; font-size: 14px; font-weight: 600; line-height: 20px; transition: background-color 200ms, color 200ms; }
.ds-alias-copy:hover { background: var(--berry); color: var(--paper); }
.ds-alias-copy:focus-visible { outline: 2px solid var(--leaf); outline-offset: 4px; }

.ds-invitation-title { display: flex; margin: 0; flex-direction: column; align-items: center; margin: 0; color: var(--wine); text-align: center; }
.ds-invitation-kicker { font-family: var(--font-bodoni), Georgia, serif; font-size: clamp(2.75rem, 12vw, 5.25rem); font-weight: 500; line-height: 0.8; letter-spacing: 0.14em; text-transform: uppercase; }
.ds-invitation-name { margin-top: 16px; color: var(--berry); font-family: var(--font-parisienne), cursive; font-size: clamp(3.5rem, 14vw, 3.75rem); font-weight: 400; line-height: 0.92; }
.ds-invitation-fest { margin-top: 32px; color: var(--berry); font-family: var(--font-parisienne), cursive; font-size: clamp(4.625rem, 23vw, 6rem); font-weight: 400; line-height: 0.88; }
